        this.closeButton.addEventListener('click', () => this.close());
        this.cancelButton.addEventListener('click', () => this.close());
        this.modalOverlay.addEventListener('click', () => this.close());

        // Confirm delete button
        this.confirmDeleteButton.addEventListener('click', () => this.handleConfirmDelete());

        // Keyboard support: Escape to close
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && this.modalDialog.classList.contains('open')) {
                this.close();
            }
        });
    }

    handleTriggerClick(event) {
        const imageName = event.currentTarget.getAttribute('data-image-name');
        this.open(imageName);
    }

    open(imageName) {
        this.currentImageName = imageName;
        this.imageNameElement.textContent = imageName;

        // Show modal and overlay
        this.modalDialog.classList.add('open');
        this.modalOverlay.classList.add('open');

        // Update ARIA attributes
        this.modalDialog.setAttribute('aria-hidden', 'false');
        this.modalOverlay.setAttribute('aria-hidden', 'false');

        // Prevent body scroll
        document.body.style.overflow = 'hidden';

        // Focus the confirm button
        this.confirmDeleteButton.focus();

        // Trap focus within modal
        this.setupFocusTrap();
    }

