        // Hide modal and overlay
        this.modalDialog.classList.remove('open');
        this.modalOverlay.classList.remove('open');

        // Update ARIA attributes
        this.modalDialog.setAttribute('aria-hidden', 'true');
        this.modalOverlay.setAttribute('aria-hidden', 'true');

        // Restore body scroll
        document.body.style.overflow = '';

        // Focus back to the trigger button
        const lastTrigger = document.querySelector('.trigger:last-of-type');
        if (lastTrigger) {
            lastTrigger.focus();
        }

        this.currentImageName = null;
        this.removeFocusTrap();
    }

    handleConfirmDelete() {
        // Simulate delete action
        console.log(`Deleting image: ${this.currentImageName}`);

        // Show success feedback (in a real app, you'd make an API call)
        this.showSuccessMessage();

        // Close the modal
        this.close();
    }

    showSuccessMessage() {
        // Create a temporary success message
        const message = document.createElement('div');
        message.className = 'success-message';
        message.setAttribute('role', 'status');
        message.setAttribute('aria-live', 'polite');
        message.textContent = `✓ "${this.currentImageName}" has been deleted`;
        document.body.appendChild(message);

        // Remove after 3 seconds
        setTimeout(() => {
            message.remove();
        }, 3000);
    }

