        this.focusTrapHandler = handleTabKey;
    }

    removeFocusTrap() {
        if (this.focusTrapHandler) {
            this.modalDialog.removeEventListener('keydown', this.focusTrapHandler);
            this.focusTrapHandler = null;
        }
    }
}

